"""Plain-text invoice lines."""


def order_line(name: str, quantity: int, unit_price: float) -> str:
    total = quantity * unit_price
    return name + ": " + quantity + " x " + f"{unit_price:.2f}" + " = " + f"{total:.2f}"


def invoice(lines: list[tuple[str, int, float]]) -> str:
    return "\n".join(order_line(*line) for line in lines)
